export function transform(callback, flush) {
    return new TransformStream({
        transform: callback,
        flush
    });
}
export function map(handler) {
    return transform((input, controller)=>controller.enqueue(handler(input)));
}
export function mapAsync(handler) {
    return transform(async (input, controller)=>controller.enqueue(await handler(input)));
}
export function tap(handler) {
    return map((input)=>{
        handler(input);
        return input;
    });
}
